<script setup>
import {ref,computed,watch,onMounted,onBeforeUnmount,nextTick} from 'vue';
import {Plus,Play,ArrowUp,ArrowDown,Trash2,Monitor,ChevronLeft,ChevronRight,ExternalLink} from 'lucide-vue-next';
import VideoWorkflowNav from './VideoWorkflowNav.vue';
import WorkspaceHeader from './WorkspaceHeader.vue';
import WorkflowAlerts from './WorkflowAlerts.vue';
import LibraryPreview from './LibraryPreview.vue';
import {useVideoWorkflow,downloadText} from '../useVideoWorkflow.js';
import {highlightScript,highlightColors,newSequence,supportKinds} from '../videoWorkflow.js';
import {imageSource,imageImportError} from '../imageImport.js';
import {renderNotebook} from '../notebookMarkdown.js';
const props=defineProps({repository:Object,videoId:String,reader:Boolean});const emit=defineEmits(['back','open-creation','workshop']);
const {project,data,error,loading,saving,dirty,recovery,storageError,load,save,flush:flushWorkflow,recover,exportDraft}=useVideoWorkflow(props,'conductor',props.reader);
defineExpose({flush});
const draftSelected=ref(!props.reader);
const selected=ref(''),reading=ref(true),fontSize=ref(28),list=ref(null),dragged=ref(null),removed=ref(null);
const sequences=computed(()=>data.value?.sequences||[]),index=computed(()=>Math.max(0,sequences.value.findIndex(s=>s.id===selected.value))),current=computed(()=>sequences.value[index.value]),next=computed(()=>sequences.value[index.value+1]);
const scriptInput=ref(null),highlightColor=ref('yellow'),imageBusy=ref(false);
let pendingImages=null;
async function flush(){if(pendingImages)await pendingImages;await flushWorkflow();}
function addImages(event){const row=current.value;const files=Array.from(event.target.files||[]);event.target.value='';if(!row||imageBusy.value)return;imageBusy.value=true;pendingImages=(async()=>{try{row.images ||= [];for(const file of files.slice(0,4-row.images.length)){if(file.type==='image/svg+xml')throw Error('Choisis une image PNG, JPEG ou WebP.');row.images.push({src:await imageSource(file),alt:file.name.slice(0,300)});}}catch(e){error.value=e.imageImport?imageImportError(e):e.message;}finally{imageBusy.value=false;pendingImages=null;}})();}
function highlight(){const field=scriptInput.value;if(!field||!current.value)return;const start=field.selectionStart,end=field.selectionEnd;const updated=highlightScript(current.value.script,start,end,highlightColor.value);if(updated.length>12000){error.value='Le script dépasse 12 000 caractères.';return;}current.value.script=updated;nextTick(()=>{field.focus({preventScroll:true});field.setSelectionRange(start,end);});}
const readerStage=ref(null),menu=ref(null),presenting=ref(false);
function openMenu(event,id){draftSelected.value=false;if(presenting.value)return;selected.value=id;menu.value={x:Math.min(event.clientX,window.innerWidth-210),y:Math.min(event.clientY,window.innerHeight-190)};}
async function present(){draftSelected.value=false;reading.value=true;presenting.value=true;try{await document.documentElement.requestFullscreen();}catch{}}
function fullscreenChanged(){if(!document.fullscreenElement)presenting.value=false;}
function closeMenu(){menu.value=null;}
function stopPresenting(){presenting.value=false;if(document.fullscreenElement)document.exitFullscreen().catch(()=>{});}
watch(()=>current.value?.id,()=>{menu.value=null;nextTick(()=>{if(readerStage.value)readerStage.value.scrollTop=0;});});
const support=computed(()=>project.value?.creations.find(c=>c.id===current.value?.creationId)),matchingSupports=computed(()=>project.value?.creations.filter(c=>c.app===current.value?.support)||[]);
watch(sequences,rows=>{if(rows.length&&!rows.some(s=>s.id===selected.value))selected.value=rows[0].id;},{deep:false});
async function go(action){try{await flush();action();}catch{}}
function add(title){draftSelected.value=false;if(sequences.value.length>=100)return;const row=newSequence(typeof title==='string'?title:'Nouvelle partie');sequences.value.push(row);selected.value=row.id;}
function starter(){for(const title of ['Accroche et objectif','Explication','Démonstration','Ce qu’il faut retenir'])add(title);selected.value=sequences.value[0].id;}
function move(from,to){if(to<0||to>=sequences.value.length||from===to)return;const [row]=sequences.value.splice(from,1);sequences.value.splice(to,0,row);}
function drop(target){const from=sequences.value.findIndex(s=>s.id===dragged.value),to=sequences.value.findIndex(s=>s.id===target);if(from>=0&&to>=0)move(from,to);dragged.value=null;}
function duplicate(){if(!current.value||sequences.value.length>=100)return;const row={...JSON.parse(JSON.stringify(current.value)),id:crypto.randomUUID(),title:current.value.title+' · copie'};sequences.value.splice(index.value+1,0,row);selected.value=row.id;}
function remove(){const at=index.value;removed.value={row:current.value,index:at};sequences.value.splice(at,1);selected.value=sequences.value[Math.min(at,sequences.value.length-1)]?.id||'';}
function undoRemove(){if(!removed.value||sequences.value.length>=100)return;sequences.value.splice(removed.value.index,0,removed.value.row);selected.value=removed.value.row.id;removed.value=null;}
function step(delta){const row=sequences.value[index.value+delta];if(row)selected.value=row.id;}
function supportChanged(){current.value.creationId='';}
function openSupport(){if(support.value)go(()=>emit('open-creation',props.videoId,support.value.app,support.value.id));}
function exportMarkdown(){downloadText('conducteur.md',`# ${project.value.name}\n\n`+sequences.value.map((s,i)=>`## ${i+1}. ${s.title}\n\n${s.script}\n\n**À montrer :** ${supportKinds.find(([k])=>k===s.support)?.[1]||''}${s.creationId?' · '+(project.value.creations.find(c=>c.id===s.creationId)?.name||'support retiré'):''}\n\n**Repères :**\n${s.cues}`).join('\n\n---\n\n'),'text/markdown;charset=utf-8');}
function keyboard(e){if(e.key==='Escape'){menu.value=null;stopPresenting();return;}if(e.key==='F12'&&!props.reader){e.preventDefault();present();return;}if(e.key==='s'&&(e.ctrlKey||e.metaKey)){e.preventDefault();save().catch(()=>{});return;}if(!reading.value||e.target.closest('input,textarea,select,[contenteditable=true]'))return;if(e.key===' '&&e.target.closest('button'))return;if(['ArrowRight','ArrowDown','PageDown',' '].includes(e.key)){e.preventDefault();step(1);}if(['ArrowLeft','ArrowUp','PageUp'].includes(e.key)){e.preventDefault();step(-1);}}
onMounted(()=>{window.addEventListener('keydown',keyboard);window.addEventListener('click',closeMenu);document.addEventListener('fullscreenchange',fullscreenChanged);});onBeforeUnmount(()=>{window.removeEventListener('keydown',keyboard);window.removeEventListener('click',closeMenu);document.removeEventListener('fullscreenchange',fullscreenChanged);if(presenting.value&&document.fullscreenElement)document.exitFullscreen().catch(()=>{});});
</script>
<template>
 <main class="production-app conductor-app" :class="{'is-reading':reading,'is-presenting':presenting}">
  <WorkspaceHeader title="" back-label="Vidéo" @back="go(()=>emit('back'))">
   <template #context><span class="creation-context-name">{{project?.name}}</span><span class="production-test">TEST</span></template>
   <template #file><button v-if="!reader" @click="save().catch(()=>{})">Enregistrer · Ctrl S</button><button :disabled="!project" @click="exportMarkdown">Exporter le conducteur en Markdown</button></template>
   <template #actions><VideoWorkflowNav v-if="!reader&&!presenting" active="conductor" @navigate="name=>go(()=>emit('workshop',name))"/><span class="save-state" role="status">{{reader?'Lecture synchronisée':saving?'Sauvegarde…':dirty?'Modifications en attente':'Enregistré'}}</span><div v-if="!reader&&!draftSelected" class="workspace-switch"><button :class="{active:!reading}" @click="reading=false">Éditer</button><button :class="{active:reading}" @click="draftSelected=false;reading=true">Aperçu</button></div><button v-if="!reader&&!presenting" class="btn primary" @click="present" title="Lancer la présentation · F12"><Play :size="16"/>Présenter</button><button v-if="presenting" class="btn" @click="stopPresenting">Quitter la lecture</button></template>
  </WorkspaceHeader>
  <WorkflowAlerts :error="error" :storage-error="storageError" :recovery="!!recovery" @retry="save().catch(()=>{})" @reload="load" @export="exportDraft" @recover="recover"/>
  <p v-if="loading" class="production-loading">Ouverture du conducteur…</p>
  <template v-else-if="project&&data">

   <div v-if="draftSelected&&!reader&&!presenting" class="conductor-draft-layout"><aside class="conductor-outline"><button class="draft-link active" aria-current="page">Brouillon</button><ol><li v-for="(row,i) in sequences" :key="row.id"><button @click="draftSelected=false;selected=row.id"><span>{{i+1}}</span><strong>{{row.title||'Sans titre'}}</strong></button></li></ol><button class="btn" @click="add">Ajouter une partie</button></aside><section class="conductor-editor conductor-draft"><h1>Brouillon</h1><p>Tes idées et notes de préparation. Cette page reste hors présentation.</p><textarea v-model="data.draft" aria-label="Brouillon de la vidéo" maxlength="20000" placeholder="Une idée, une question à creuser, un plan provisoire…"/></section></div>
   <div v-else-if="!sequences.length" class="production-empty"><span class="eyebrow">DU PLAN À L’ÉCRAN</span><h1>Garde le fil de ta vidéo.</h1><p v-if="reader">Le conducteur est encore vide. Ajoute des parties dans la fenêtre de préparation.</p><template v-else><p>Prépare ce que tu dis, ce que tu montres et tes repères. Puis garde ce déroulé sous les yeux pendant ton tournage continu.</p><div class="production-actions"><button class="btn primary" @click="add">Créer ma première partie</button><button class="btn" @click="starter">Commencer avec un plan simple</button></div></template></div>
   <div v-else-if="reading" class="conductor-reader">
    <aside class="reader-outline"><button v-if="!reader&&!presenting" class="draft-link" @click="draftSelected=true">Brouillon</button><span class="eyebrow">LE FIL DE LA VIDÉO</span><button v-for="(row,i) in sequences" :key="row.id" @contextmenu.prevent="!reader&&openMenu($event,row.id)" :class="{active:row.id===current?.id}" @click="draftSelected=false;selected=row.id"><span>{{String(i+1).padStart(2,'0')}}</span>{{row.title||'Sans titre'}}</button></aside>
    <section ref="readerStage" v-if="current" class="reader-stage" :style="{'--reader-size':Math.max(18,Math.min(60,Number(fontSize)||28))+'px'}"><div class="reader-progress"><span>PARTIE {{index+1}} / {{sequences.length}}</span><label>Taille de lecture<input v-model.number="fontSize" type="number" min="18" max="60" aria-label="Taille du texte en lecture">px</label></div><h1>{{current.title||'Sans titre'}}</h1><div class="reader-content"><div :key="current.id" class="reader-script notebook-preview" v-html="renderNotebook(current.script||'*Aucun script pour cette partie.*')"/><div v-if="current.images?.length" class="reader-illustrations"><figure v-for="(picture,i) in current.images" :key="i"><img :src="picture.src" :alt="picture.alt"><figcaption v-if="picture.alt">{{picture.alt}}</figcaption></figure></div></div><aside v-if="current.cues" class="reader-cues"><span class="eyebrow">MES REPÈRES</span><div class="notebook-preview" v-html="renderNotebook(current.cues)"/></aside><div class="reader-support"><Monitor :size="17"/><span>{{supportKinds.find(([k])=>k===current.support)?.[1]}}<strong v-if="support"> · {{support.name}}</strong><small v-else-if="current.creationId"> · Support retiré de la vidéo</small></span></div><footer><button class="btn" :disabled="index===0" @click="step(-1)"><ChevronLeft :size="16"/>Précédente</button><span>{{next?'Ensuite : '+(next.title||'Sans titre'):'Fin du conducteur'}}<small>← → · Espace pour avancer · aucun minutage imposé</small></span><button class="btn primary" :disabled="index===sequences.length-1" @click="step(1)">Suivante<ChevronRight :size="16"/></button></footer></section>
   </div>
   <div v-else class="conductor-layout">
    <aside class="conductor-outline"><button class="draft-link" @click="draftSelected=true">Brouillon</button><header><div><span class="eyebrow">DÉROULÉ</span><strong>{{sequences.length}} parties</strong></div><button class="icon-btn" :disabled="sequences.length>=100" aria-label="Ajouter une partie" @click="add"><Plus :size="19"/></button></header><ol ref="list"><li v-for="(row,i) in sequences" :key="row.id" @contextmenu.prevent="openMenu($event,row.id)" :class="{active:row.id===current?.id}" @dragover.prevent @drop.prevent="drop(row.id)"><button draggable="true" @dragstart="dragged=row.id;$event.dataTransfer.setData('text/plain',row.id)" @dragend="dragged=null" @click="draftSelected=false;selected=row.id"><span>{{String(i+1).padStart(2,'0')}}</span><div><strong>{{row.title||'Sans titre'}}</strong><small>{{supportKinds.find(([k])=>k===row.support)?.[1]}}</small></div></button><div class="outline-move"><button class="icon-btn" :aria-label="'Options de la partie '+(i+1)" @click.stop="openMenu($event,row.id)">⋯</button><button class="icon-btn" :aria-label="'Supprimer la partie '+(i+1)" @click="selected=row.id;remove()"><Trash2 :size="13"/></button><button class="icon-btn" :disabled="i===0" :aria-label="'Monter la partie '+(i+1)" @click="move(i,i-1)"><ArrowUp :size="13"/></button><button class="icon-btn" :disabled="i===sequences.length-1" :aria-label="'Descendre la partie '+(i+1)" @click="move(i,i+1)"><ArrowDown :size="13"/></button></div></li></ol><button class="btn" :disabled="sequences.length>=100" @click="add"><Plus :size="15"/>Ajouter une partie</button></aside>
    <section v-if="current" class="conductor-editor"><div v-if="removed" class="production-undo" role="status">Partie supprimée.<button class="btn" :disabled="sequences.length>=100" @click="undoRemove">Annuler</button></div><header class="production-editor-heading"><span class="eyebrow">PARTIE {{index+1}}</span></header><input v-model="current.title" class="sequence-title" aria-label="Titre de la partie" placeholder="Le titre de cette partie" maxlength="200">    <aside v-if="current" class="conductor-support"><span class="eyebrow">CE QUE JE MONTRE</span><label class="production-field">Support<select v-model="current.support" aria-label="Type de support" @change="supportChanged"><option v-for="[id,label] in supportKinds" :key="id" :value="id">{{label}}</option></select></label><template v-if="['slides','banners'].includes(current.support)"><label class="production-field">Création existante<select v-model="current.creationId" aria-label="Création associée"><option value="">Choisir plus tard</option><option v-for="row in matchingSupports" :key="row.id" :value="row.id">{{row.name}}</option></select></label><p v-if="current.creationId&&!support" class="field-help">Cette création a été retirée de la vidéo.</p><button v-if="support" :key="support.id" class="support-preview" @click="openSupport"><LibraryPreview :repository="repository" :creation="support"/><span>Ouvrir {{support.name}}<ExternalLink :size="14"/></span></button><p v-else class="field-help">Les créations de la fiche vidéo sont proposées ici. Aucun document n’est dupliqué.</p></template><p v-else class="field-help">Ce repère t’indique où porter ton attention pendant l’enregistrement.</p></aside><div class="conductor-writing-toolbar"><span>Sélectionne un passage à surligner</span><select v-model="highlightColor" aria-label="Couleur du surligneur"><option value="yellow">Jaune</option><option value="mint">Menthe</option><option value="blue">Bleu</option><option value="pink">Rose</option><option value="orange">Orange</option></select><button class="btn" @mousedown.prevent @click="highlight">Surligner la sélection</button></div><label class="production-field">Ce que je dis <span>Script rédigé ou quelques points · Markdown</span><textarea ref="scriptInput" v-model="current.script" aria-label="Script de la partie" maxlength="12000" rows="12" placeholder="L’explication que je veux donner…"/></label><section class="conductor-images"><div class="publication-field-label"><span>Illustrations · {{current.images?.length||0}} / 4</span><label class="btn">{{imageBusy?'Préparation…':'Ajouter des images'}}<input type="file" accept="image/png,image/jpeg,image/webp" multiple :disabled="imageBusy||(current.images?.length||0)>=4" @change="addImages" hidden></label></div><div class="conductor-image-grid"><figure v-for="(picture,i) in current.images" :key="i"><img :src="picture.src" :alt="picture.alt"><input v-model="picture.alt" aria-label="Légende de l’illustration" maxlength="300"><button class="icon-btn" :aria-label="'Retirer l’illustration '+(i+1)" @click="current.images.splice(i,1)"><Trash2 :size="15"/></button></figure></div></section><label class="production-field">Mes repères <span>Consignes que tu ne prononces pas : pauses, gestes, points à montrer · Markdown</span><textarea v-model="current.cues" aria-label="Repères de la partie" maxlength="3000" rows="4" placeholder="Laisser le résultat visible avant de poursuivre…"/></label></section>

   </div>
   <div v-if="removed&&!reader&&reading" class="production-undo">Partie supprimée.<button class="btn" @click="undoRemove">Annuler</button></div>
   <div v-if="!sequences.length&&removed&&!reader" class="production-undo">Dernière partie supprimée.<button class="btn" @click="undoRemove">Annuler</button></div>
  </template>
  <div v-if="menu" role="menu" aria-label="Actions de la partie" class="conductor-context" :style="{left:menu.x+'px',top:menu.y+'px'}" @click="menu=null">
   <button role="menuitem" @click="reading=false">Modifier la partie</button><button role="menuitem" :disabled="sequences.length>=100" @click="duplicate">Dupliquer la partie</button><button role="menuitem" :disabled="index===0" @click="move(index,index-1)">Monter</button><button role="menuitem" :disabled="index===sequences.length-1" @click="move(index,index+1)">Descendre</button><button role="menuitem" @click="remove">Supprimer la partie</button>
  </div>
 </main>
</template>
